CREATE OR REPLACE FUNCTION <schema>.guard_open_grace_subscription_delete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
                    BEGIN
                        IF EXISTS (
                            SELECT 1 FROM grace_access_sessions
                            WHERE subscription_id = OLD.id
                              AND state IN ('pending', 'active', 'restoring')
                        ) THEN
                            RAISE EXCEPTION 'subscription has an open grace-access session'
                                USING ERRCODE = '23503';
                        END IF;
                        RETURN OLD;
                    END;
                    $function$
